        var text=String(title?title+"：":"")+String(msg==null?"":msg);
        try{
          var p=(g.parent&&g.parent!==g)?g.parent:null;
          if(p&&typeof p.__liyuanToast==="function"){p.__liyuanToast(level,text);return;}
        }catch(e){}
